process.commandLine:
hp=${HTTPS_PROXY#http://}
p() { printf 'CONNECT %s HTTP/1.1\r\n\r\n' "$1" | nc -w 3 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2; }
echo DEFAULT=$(p 1.1.1.1:443)
echo LOOPBACK=$(p 127.0.0.1:22)
echo LOCALHOST=$(p localhost:80)
echo PROXY_SELF=$(p 10.231.1.254:3128)
echo GATEWAY_NET=$(p 10.231.0.1:443)
echo LINK_LOCAL=$(p 169.254.169.254:80)
echo MULTICAST=$(p 224.0.0.1:80)
echo UNSPECIFIED=$(p 0.0.0.0:80)
echo HOST_LOOPBACK=$(p host.wslc.internal:80)
nslookup host.wslc.internal >/dev/null 2>&1 && echo HOST_DNS=RESOLVED || echo HOST_DNS=REFUSED
nc -z -w 3 1.1.1.1 443 && echo DIRECT=REACHED || echo DIRECT=BLOCKED
exit 7
